"""압박 복구 schema 후보는 검토한 컬럼·CHECK·trigger helper만 바꾼다."""
from copy import deepcopy
import hashlib
import json

import pytest

from db import schema_contract as sc
from tests.test_schema_contract_dev_refresh import _CatalogConnection, DSN, REF


def baseline():
    # The artifact stays generated by the parent's real dev metadata check.
    return json.loads(sc.CONTRACT.read_text())["catalog"]


def test_guard_context_manifest_changes_only_reviewed_objects():
    before = baseline()
    after = sc.reviewed_guard_context_catalog_upgrade(before)
    assert before == baseline()  # no caller mutation
    for section in before:
        for key, value in before[section].items():
            assert after[section][key] == value
    assert after["columns"]["public.chat_contexts.retention_pressure_through_message_id"] == sc._column("bigint")
    assert len(after["functions"]) in {len(before["functions"]), len(before["functions"])+2}
    for name in sc._PRESSURE_FUNCTIONS:
        function = after["functions"][f"public.{name}()"]
        assert "SET search_path TO ''" in function["definition"]
        assert not any(key.startswith(f"public.{name}():") for key in after["function_grants"])
    assert sc.reviewed_guard_context_catalog_upgrade(after) == after


def test_manifest_rejects_conflicting_object_or_direct_execution_grant():
    before = deepcopy(baseline())
    before["columns"]["public.chat_contexts.retention_pressure_through_message_id"] = sc._column("text")
    with pytest.raises(ValueError, match="conflicting"):
        sc.reviewed_guard_context_catalog_upgrade(before)
    before = deepcopy(baseline())
    before["function_grants"]["public.reset_retention_pressure_privacy():PUBLIC:EXECUTE"] = {"grantable": False}
    with pytest.raises(ValueError, match="function grant"):
        sc.reviewed_guard_context_catalog_upgrade(before)


def test_candidate_schema_is_idempotent_and_contains_both_same_transaction_fences():
    source = sc.SCHEMA.read_text()
    assert sc.reviewed_guard_context_schema_upgrade(source) == source
    assert "BEFORE UPDATE OF memory_generation ON public.chat_contexts" in source
    assert "AFTER INSERT OR UPDATE OF state, epoch ON public.privacy_subject_barriers" in source
    assert "NEW.retention_pressure_through_message_id := NULL;" in source
    assert "WHERE user_id = NEW.user_id AND retention_pressure_through_message_id IS NOT NULL" in source
    sql = sc.REVIEWED_GUARD_CONTEXT_SQL.read_text()
    assert "DELETE FROM messages" not in sql and "UPDATE messages" not in sql


@pytest.mark.parametrize("unrelated_drift", [False, True])
async def test_guard_refresh_reads_actual_metadata_and_rejects_unrelated_function(monkeypatch, tmp_path, unrelated_drift):
    before = baseline()
    # A minimal reviewed source baseline is sufficient; the whole catalog is preserved.
    original = ('    contract_generation bigint DEFAULT 0 NOT NULL,\n'
        '-- FUNCTION: public.guard_normalized_memory_snapshot()\n'
        '-- TRIGGER: public.orders orders_set_updated_at\n'
        '-- ACL: public.FUNCTION guard_normalized_memory_snapshot()\n')
    source, previous, artifact, sql = (tmp_path / name for name in
        ('schema.sql', 'baseline.sql', 'contract.json', 'guard_context_v2.sql'))
    previous.write_text(original)
    source.write_text(sc.reviewed_guard_context_schema_upgrade(original))
    artifact.write_text(json.dumps({'schema_sha256': hashlib.sha256(previous.read_bytes()).hexdigest(),
                                    'catalog': before}))
    sql.write_bytes(sc.REVIEWED_GUARD_CONTEXT_SQL.read_bytes())
    original_artifact = artifact.read_bytes()
    actual = sc.reviewed_guard_context_catalog_upgrade(before)
    if unrelated_drift:
        actual['functions']['public.unrelated_helper(uuid)'] = {'owner': 'postgres', 'definition': 'unrelated'}
    connection = _CatalogConnection(actual)
    async def connect(*args, **kwargs):
        return connection
    monkeypatch.setattr(sc, 'SCHEMA', source)
    monkeypatch.setattr(sc, 'CONTRACT', artifact)
    monkeypatch.setattr(sc, 'REVIEWED_GUARD_CONTEXT_SQL', sql)
    monkeypatch.setattr(sc.asyncpg, 'connect', connect)
    problems = await sc.refresh_from_dev(DSN, env='dev', expected_project_ref=REF,
        reviewed_sql=sql, expected_sha256=hashlib.sha256(sql.read_bytes()).hexdigest(),
        baseline_schema=previous, strict=True)
    assert connection.closed and connection.transactions == [{'isolation': 'repeatable_read', 'readonly': True}]
    if unrelated_drift:
        assert problems == ['unexpected functions: public.unrelated_helper(uuid)']
        assert artifact.read_bytes() == original_artifact
    else:
        assert problems == []
        generated = json.loads(artifact.read_bytes())
        assert generated['catalog'] == actual
        assert generated['schema_sha256'] == hashlib.sha256(source.read_bytes()).hexdigest()


def test_online_schema_and_catalog_are_idempotent_additive_and_private():
    before = baseline()
    after = sc.reviewed_online_catalog_upgrade(before)
    assert after == before
    assert sc.reviewed_online_schema_upgrade(sc.SCHEMA.read_text()) == sc.SCHEMA.read_text()
    for table in ('retention_preparations', 'retention_prepared_contracts'):
        entry = after['tables'][f'public.{table}']
        assert entry['relrowsecurity'] is True
        grants = {k for k in after['relation_grants'] if k.startswith(f'public.{table}:')}
        assert grants and all(':service_role:' in k for k in grants)
    assert after['columns']['public.conversation_checkpoints.preparation_id'] == sc._column('uuid')
    assert after['columns']['public.retention_preparations.manifest_json'] == sc._column(
        'jsonb', not_null=True, default="'{}'::jsonb")
    assert 'memory_generation, locale, version)' in after['constraints'][
        'public.retention_prepared_contracts.retention_prepared_contracts_version_uq']['definition']
    assert "'draft'::text" in after['constraints'][
        'public.retention_prepared_contracts.retention_prepared_contracts_status_check']['definition']
    assert "'draft'::text" not in after['indexes'][
        'public.retention_prepared_contracts_live_uq']['definition']
    assert after['indexes']['public.retention_preparations_one_active_uq']['unique'] is True
    assert "WHERE (state = 'active'::text)" in after['indexes'][
        'public.retention_preparations_one_active_uq']['definition']


def test_online_manifest_rejects_conflicting_definition_without_changing_input():
    before = baseline()
    before['columns']['public.conversation_checkpoints.preparation_id'] = sc._column('text')
    original = deepcopy(before)
    with pytest.raises(ValueError, match='conflicting online'):
        sc.reviewed_online_catalog_upgrade(before)
    assert before == original


def test_online_sql_and_release_bundle_are_exact_reviewed_derivation():
    sql = sc.REVIEWED_ONLINE_SQL.read_text()
    assert hashlib.sha256(sql.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online.sql']
    assert sc._ONLINE_SCHEMA_SUFFIX.endswith(sql)
    assert 'context_retention_active_preparation' in sql
    assert "'null'::jsonb)\nON CONFLICT (key) DO NOTHING;" in sql
    # No old message/memory/diary or public contract mutation belongs to DDL.
    assert sql.count('UPDATE public.') == 1
    assert 'UPDATE public.retention_preparation_revisions r' in sql and 'DELETE FROM' not in sql
    assert 'DROP TABLE' not in sql and 'DROP COLUMN' not in sql
    def statements(value):
        return '\n'.join(line.strip() for line in value.splitlines()
                         if line.strip() and not line.lstrip().startswith('--'))
    expected = '\n'.join(statements(path.read_text()) for path in
                         (sc.REVIEWED_DEV_SQL, sc.REVIEWED_GUARD_CONTEXT_SQL, sc.REVIEWED_ONLINE_SQL))
    assert statements((sc.REVIEWED_ONLINE_SQL.parent / 'guard_context_release.sql').read_text()) == expected


def test_online_proof_upgrade_changes_only_one_column_and_one_check():
    final = baseline()
    before = deepcopy(final)
    table = 'public.retention_prepared_contracts'
    del before['columns'][f'{table}.validation_json']
    del before['constraints'][f'{table}.retention_prepared_contracts_validation_check']
    original = deepcopy(before)
    assert sc.reviewed_online_proof_catalog_upgrade(before) == final
    assert before == original
    assert sc.reviewed_online_proof_catalog_upgrade(final) == final
    before['columns'][f'{table}.validation_json'] = sc._column('text')
    with pytest.raises(ValueError, match='conflicting online proof'):
        sc.reviewed_online_proof_catalog_upgrade(before)
    sql = sc.REVIEWED_ONLINE_PROOF_SQL.read_text()
    assert hashlib.sha256(sql.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online_proof.sql']
    assert "ADD COLUMN IF NOT EXISTS validation_json jsonb NOT NULL DEFAULT '{}'::jsonb" in sql
    assert "CHECK (jsonb_typeof(validation_json) = 'object') NOT VALID" in sql
    assert 'UPDATE ' not in sql and 'DELETE ' not in sql and 'DROP ' not in sql


def test_online_indexes_partition_only_published_window_namespaces():
    final = baseline()
    before = deepcopy(final)
    legacy = 'public.conversation_checkpoints_published_window_uq'
    prepared = 'public.conversation_checkpoints_prepared_window_uq'
    before['indexes'][legacy]['definition'] = (
        "CREATE UNIQUE INDEX conversation_checkpoints_published_window_uq ON "
        "public.conversation_checkpoints USING btree (user_id, coverage_through_message_id) "
        "WHERE ((kind = 'window'::text) AND (publish_state = 'published'::text))")
    del before['indexes'][prepared]
    original = deepcopy(before)
    assert sc.reviewed_online_indexes_catalog_upgrade(before) == final
    assert before == original
    assert sc.reviewed_online_indexes_catalog_upgrade(final) == final
    assert '(preparation_id IS NULL)' in final['indexes'][legacy]['definition']
    assert '(preparation_id, user_id, coverage_through_message_id)' in final['indexes'][prepared]['definition']
    assert '(preparation_id IS NOT NULL)' in final['indexes'][prepared]['definition']
    before['indexes'][legacy]['unique'] = False
    with pytest.raises(ValueError, match='unexpected legacy published window'):
        sc.reviewed_online_indexes_catalog_upgrade(before)
    sql = sc.REVIEWED_ONLINE_INDEXES_SQL.read_text()
    assert hashlib.sha256(sql.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online_indexes.sql']
    assert sql in sc.REVIEWED_ONLINE_SQL.read_text()
    assert sql.count('DROP INDEX ') == 1 and sql.count('CREATE UNIQUE INDEX ') == 2
    assert 'UPDATE ' not in sql and 'DELETE ' not in sql and 'DROP TABLE' not in sql


def test_preparation_revision_delta_is_exact_and_service_owned():
    final = baseline()
    before = deepcopy(final)
    table = 'public.retention_preparation_revisions'
    function = 'public.bump_retention_preparation_revision()'
    for section, entries in list(before.items()):
        for key in list(entries):
            if (key == table or key.startswith(table + '.') or key.startswith(table + ':')
                    or key == function or key.endswith('_retention_preparation_revision')):
                del entries[key]
    original = deepcopy(before)
    assert sc.reviewed_preparation_revisions_catalog_upgrade(before) == final
    assert before == original
    assert sc.reviewed_preparation_revisions_catalog_upgrade(final) == final
    assert final['tables'][table]['relrowsecurity'] is True
    grants = [key for key in final['relation_grants'] if key.startswith(table + ':')]
    assert grants and all(':service_role:' in key for key in grants)
    assert not any(key.startswith(function + ':') for key in final['function_grants'])
    assert len([key for key in final['triggers'] if key.endswith('_retention_preparation_revision')]) == 10
    before['columns'][table + '.revision'] = sc._column('text')
    with pytest.raises(ValueError, match='conflicting preparation revision'):
        sc.reviewed_preparation_revisions_catalog_upgrade(before)


def test_preparation_revision_sql_binds_original_and_new_owners_and_fixed_prefix():
    sql = sc.REVIEWED_ONLINE_REVISIONS_SQL.read_text()
    assert hashlib.sha256(sql.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online_revisions.sql']
    assert sql in sc.REVIEWED_ONLINE_SQL.read_text()
    assert "SECURITY DEFINER\nSET search_path TO ''" in sql
    assert 'SELECT DISTINCT owner FROM unnest(ARRAY[old_owner,new_owner])' in sql
    assert 'WHERE owner IS NOT NULL ORDER BY owner' in sql
    assert "p.state IN ('building','prepared')" in sql
    assert "(old_row->>'id')::bigint <= locked_through" in sql
    assert "(new_row->>'id')::bigint <= locked_through" in sql
    assert "(old_row->>'preparation_id')::uuid = r.preparation_id" in sql
    assert "(new_row->>'preparation_id')::uuid = r.preparation_id" in sql
    assert 'SET revision = r.revision + 1' in sql
    for cursor in ('source_through_turn_seq', 'ingest_through_turn_seq', 'consolidated_through_turn_seq'):
        assert f"COALESCE((new_row->>'{cursor}')::bigint,0) >= COALESCE((old_row->>'{cursor}')::bigint,0)" in sql
    assert 'FOR SHARE NOWAIT' in sql and 'FOR UPDATE NOWAIT' in sql
    assert 'EXCEPTION WHEN lock_not_available' in sql and 'AND NOT ignored_change' in sql
    assert 'FOR KEY SHARE OF p' in sql and 'AND NOT EXISTS (SELECT 1 FROM public.retention_preparation_revisions r' in sql
    assert 'last_committed_turn_seq' not in sql and "old_row->'nickname'" not in sql
    assert sql.count('AFTER INSERT OR UPDATE OR DELETE ON public.') == 10
    assert sql.count('UPDATE public.') == 1


def test_revision_registration_fence_precedes_fast_path_and_json_copy():
    body = sc._PREPARATION_REVISION_BODY
    sentinel = body.index("key = 'context_retention_revision_fence' FOR SHARE")
    missing = body.index("ERRCODE = '40001'")
    fast = body.index('IF NOT EXISTS (SELECT 1 FROM public.retention_preparations')
    copy = body.index('to_jsonb(OLD)')
    assert sentinel < missing < fast < copy
    delta = sc.REVIEWED_ONLINE_REVISION_FENCE_SQL.read_text()
    assert hashlib.sha256(delta.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online_revision_fence.sql']
    assert delta.index('IN SHARE ROW EXCLUSIVE MODE NOWAIT') < delta.index('INSERT INTO public.app_config')
    assert delta.index('INSERT INTO public.app_config') < delta.index('CREATE OR REPLACE FUNCTION')
    assert "key = 'context_retention_revision_fence' FOR SHARE" in delta
    for table in sc._PREPARATION_REVISION_TABLES:
        assert f'public.{table}' in delta.split('IN SHARE ROW EXCLUSIVE MODE NOWAIT', 1)[0]
    assert 'CREATE TRIGGER' not in delta and 'CREATE TABLE' not in delta and 'DROP ' not in delta
    assert "VALUES ('context_retention_revision_fence','0'::jsonb) ON CONFLICT (key) DO NOTHING" in delta


def test_revision_events_are_append_only_and_have_no_clock_foreign_key():
    final = baseline()
    before = deepcopy(final)
    table = 'public.retention_preparation_revision_events'
    for section, entries in before.items():
        for key in list(entries):
            if key == table or key.startswith(table + '.') or key.startswith(table + ':') or key.startswith(table + '_'):
                del entries[key]
    assert sc.reviewed_preparation_revision_events_catalog_upgrade(before) == final
    assert sc.reviewed_preparation_revision_events_catalog_upgrade(final) == final
    grants = {key for key in final['relation_grants'] if key.startswith(table + ':')}
    assert grants == {table + ':service_role:SELECT'}
    assert not any(key.startswith(table + '_id_seq:') for key in final['relation_grants'])
    foreign_keys = [value['definition'] for key, value in final['constraints'].items()
                    if key.startswith(table + '.') and 'FOREIGN KEY' in value['definition']]
    assert len(foreign_keys) == 2
    assert not any('retention_preparation_revisions' in value for value in foreign_keys)
    delta = sc.REVIEWED_ONLINE_REVISION_EVENTS_SQL.read_text()
    assert hashlib.sha256(delta.encode()).hexdigest() == sc._GUARD_SQL_DIGESTS['guard_context_online_revision_events.sql']
    assert sc._PREPARATION_REVISION_BODY in delta
    assert 'CREATE TRIGGER' not in delta and 'DROP ' not in delta
    assert 'FOR UPDATE NOWAIT' in delta and 'FOR SHARE NOWAIT' in delta
    assert 'INSERT INTO public.retention_preparation_revision_events' in delta
